    // Derive layout data from actual matching children, including after live edits.
    // Observing childList only keeps our own custom-property updates loop-free.
    const itemSelector = '.spectrum-card, .fan-card, .circle-orb';
    function syncItems(group) {
      // Newly inserted seasonal cards receive the spectrum treatment automatically.
      for (const child of group.children) {
        if (child.matches('.card')) child.classList.add('spectrum-card');
      }
      const items = [...group.children].filter(child => child.matches(itemSelector));
      group.style.setProperty('--item-count', items.length);
      items.forEach((item, index) => {
        item.style.setProperty('--item-index', index);
        item.style.setProperty('--item-count', items.length);
      });
    }
    document.querySelectorAll('[data-dynamic-group]').forEach(group => {
      syncItems(group);
      new MutationObserver(() => syncItems(group)).observe(group, { childList: true });
    });
  </script>
